"""Structural diagnostics for two complete designs. No classifier fitting."""
from collections import Counter
from pathlib import Path
import hashlib, json, importlib.util, sys, io
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from IPython.display import display, Image


def _digest(obj):
    return hashlib.sha256(json.dumps(obj, sort_keys=True, separators=(',', ':')).encode()).hexdigest()


def _check_split(seed, train, queries, partners, neighbors, removed_train, removed_queries):
    labels = list(neighbors)
    owners = {w: label for label, words in neighbors.items() for w in words}
    if len(owners) != sum(map(len, neighbors.values())):
        raise ValueError('Overlapping catalogue classes.')
    if len(train) != len(set(train)) or len(queries) != len(set(queries)):
        raise ValueError('Repeated words inside a split.')
    if set(partners) != set(queries):
        raise ValueError('Missing or extra query-to-neighbor assignments.')
    if not (set(train) | set(queries) | set(partners.values())) <= set(owners):
        raise ValueError('Words outside the authenticated catalogue.')
    tc = Counter(owners[w] for w in train)
    qc = Counter(owners[w] for w in queries)
    train_set = set(train)
    flags = dict(overlap=0, missing_neighbor=0, unsupported_class=0,
                 low_query_support=0, low_train_support=0, self_pair=0)
    violations = []
    for word in queries:
        label = owners[word]; neighbor = partners[word]
        conditions = dict(overlap=word in train_set, missing_neighbor=neighbor not in train_set,
                          unsupported_class=tc[label] == 0, low_query_support=qc[label] < 3,
                          low_train_support=tc[label] < 3, self_pair=word == neighbor)
        for key, value in conditions.items():
            flags[key] += int(value)
            if value:
                violations.append(dict(split_seed=seed, query_word=word, query_class=label,
                                       neighbor_word=neighbor, check=key))
    # Also count low-support TRAIN classes with no validation queries.
    low_train_cells = sum(0 < tc[label] < 3 for label in labels)
    row = dict(split_seed=seed, train_words=len(train), validation_words=len(queries),
               removed_train=int(removed_train), removed_validation=int(removed_queries),
               train_class_cells_below_minimum=low_train_cells,
               all_train_classes=all(tc[x] >= 3 for x in labels),
               all_validation_classes=all(qc[x] >= 3 for x in labels),
               all_checks_pass=not any(flags.values()) and low_train_cells == 0, **flags)
    classes = [dict(split_seed=seed, label=label, train_count=tc[label],
                    validation_count=qc[label]) for label in labels]
    return row, classes, violations


def _pack(rows, classes, violations, query_words, neighbors, provenance):
    if sorted(r['split_seed'] for r in rows) != list(range(51)):
        raise ValueError('Exactly 51 distinct splits are required.')
    return dict(splits=rows, class_counts=classes, violations=violations,
                labels=list(neighbors), catalogue_words=sum(map(len, neighbors.values())),
                distinct_validation_words=len(set(query_words)), provenance=provenance)


def _summary(audit):
    d = pd.DataFrame(audit['splits']); c = pd.DataFrame(audit['class_counts'])
    return {
        'Splits audited': len(d),
        'Catalogue words': audit['catalogue_words'],
        'Distinct validation words': audit['distinct_validation_words'],
        'Query-split observations': int(d.validation_words.sum()),
        'TRAIN/validation overlap (word-splits)': int(d.overlap.sum()),
        'Queries with neighbor absent from TRAIN': int(d.missing_neighbor.sum()),
        'Queries with class absent from TRAIN': int(d.unsupported_class.sum()),
        'Queries with validation-class support < 3': int(d.low_query_support.sum()),
        'Queries with TRAIN-class support < 3': int(d.low_train_support.sum()),
        'Nonempty TRAIN class-splits with support < 3': int(d.train_class_cells_below_minimum.sum()),
        'Self-paired queries': int(d.self_pair.sum()),
        'Splits passing all shared structural checks': int(d.all_checks_pass.sum()),
        'Splits with all eight TRAIN classes (>= 3 words)': int(d.all_train_classes.sum()),
        'Splits with all eight validation classes (>= 3 words)': int(d.all_validation_classes.sum()),
        'Minimum TRAIN words per class, including absent classes': int(c.train_count.min()),
        'Minimum validation words per class, including absent classes': int(c.validation_count.min()),
        'Removed TRAIN words (word-splits)': int(d.removed_train.sum()),
        'Removed validation words (word-splits)': int(d.removed_validation.sum()),
    }


def _render_comparison(baseline, proposed, output=None):
    if baseline['labels'] != proposed['labels']:
        raise ValueError('Class labels or class order differ.')
    names = ['Antecedent (K20)', 'Proposed static (K40)']
    audits = [baseline, proposed]
    identity = _digest(audits)
    out = Path(output) if output is not None else Path.home()/'E2_Contrasts'/'structural_audit'/identity[:12]
    out.mkdir(parents=True, exist_ok=True)
    table = pd.DataFrame({name: _summary(a) for name, a in zip(names, audits)})
    table.index.name = 'Diagnostic'
    display(table)
    table.to_csv(out/'structural_comparison.csv')
    class_tables = []
    for name, a in zip(names, audits):
        counts = pd.DataFrame(a['class_counts'])
        counts.insert(0, 'Design', name)
        class_tables.append(counts)
    class_counts = pd.concat(class_tables, ignore_index=True)
    class_counts.to_csv(out/'class_counts_by_split.csv', index=False)
    with plt.rc_context({'font.size': 11, 'font.family': 'DejaVu Sans'}):
        fig, axes = plt.subplots(1, 2, figsize=(14, 4.8), constrained_layout=True)
        for ax, field, title in zip(axes, ['train_count', 'validation_count'],
                                   ['Minimum TRAIN support', 'Minimum validation support']):
            for j, (name, a) in enumerate(zip(names, audits)):
                minima = pd.DataFrame(a['class_counts']).groupby('label')[field].min().reindex(a['labels'])
                bars = ax.bar(np.arange(8)+(j-.5)*.36, minima, width=.36,
                              label=name, color=['#6A0DAD', '#D890D1'][j])
                for b, count in zip(bars, minima):
                    ax.text(b.get_x()+b.get_width()/2, count+.15, str(int(count)),
                            ha='center', va='bottom', fontsize=9)
            ax.axhline(3, color='#555555', linestyle='--', linewidth=1, label='Minimum requirement (3)')
            ax.set_xticks(range(8), baseline['labels'], rotation=45, ha='right')
            ax.set(title=title, ylabel='Minimum words across 51 splits', xlabel='Class')
            ax.set_ylim(0, max(4, ax.get_ylim()[1])+2)
            ax.spines[['top', 'right']].set_visible(False)
        handles, legend_labels = axes[0].get_legend_handles_labels()
        fig.legend(handles, legend_labels, loc='upper center', bbox_to_anchor=(.5, 1.12),
                   ncol=3, fontsize=10, frameon=False)
        for ext in ['png', 'pdf']:
            fig.savefig(out/('minimum_class_support.'+ext), dpi=220, bbox_inches='tight', facecolor='white')
        plt.close(fig)
    display(Image(filename=str(out/'minimum_class_support.png'), width=1100))
    violations = pd.DataFrame([dict(Design=name, **v) for name,a in zip(names,audits) for v in a['violations']],
                             columns=['Design','split_seed','query_word','query_class','neighbor_word','check'])
    violations.to_csv(out/'query_violations.csv', index=False)
    if not violations.empty:
        print('Observed query-level violations (first 30 rows; full table saved):')
        display(violations.head(30))
    else:
        print('No query-level violations were observed for the shared checks in either design.')
    if all(all(r['all_checks_pass'] for r in a['splits']) for a in audits):
        print('Both designs pass the shared checks on these 51 splits. These data do not demonstrate a structural failure of the antecedent.')
    print('Class coverage is reported separately: an absent class differs from an under-supported retained class.')
    print('TRAIN means the stored pattern set, not the classifier internal fitting subset.')
    print('Descriptive comparison of complete designs; no isolated causal effect or FAR change is estimated.')
    for name,a in zip(['antecedent','static'], audits):
        pd.DataFrame(a['splits']).to_csv(out/(name+'_splits.csv'), index=False)
        (out/(name+'_audit.json')).write_text(json.dumps(a, indent=2, allow_nan=False), encoding='utf-8')
    print('Saved figures and tables:', out)
    return table, out


def run_structural_comparison(result, module=None, embedding_file=None, vectors=None):
    ctx, module, neighbors, embeddings, geo = _load_static(result, module, embedding_file, vectors)
    expected = ctx['expected'].copy()
    if expected.duplicated(['split_seed', 'word']).any() or set(expected.split_seed) != set(range(51)):
        raise ValueError('The saved validation inventory must contain all 51 splits.')
    rows, classes, violations, query_words = [], [], [], []
    for seed in range(51):
        sp = module.prepare_classification_split(embeddings, neighbors, metric='cosine',
             frequency_threshold=2, validation_split=.33, random_seed_split=seed,
             pairwise_different_class=True, debug=False)
        got = pd.DataFrame(dict(word=sp.validation_words, true_class=sp.true_classes,
                               validation_similarity=np.clip(sp.validation_similarities,-1,1))).sort_values('word').reset_index(drop=True)
        saved = expected.loc[expected.split_seed.eq(seed), got.columns].sort_values('word').reset_index(drop=True)
        pd.testing.assert_frame_equal(got, saved, check_dtype=False, check_exact=False, rtol=0, atol=1e-12)
        all_pairs = {w:v for w,v,d in sp.nearest_neighbor_pairs}
        partners = {w:all_pairs[w] for w in sp.validation_words}
        r,c,v = _check_split(seed, sp.train_words, sp.validation_words, partners, neighbors,
            sp.drop_info['n_training_before_filter']-len(sp.train_words),
            sp.drop_info['n_validation_before_filter']-len(sp.validation_words))
        rows.append(r); classes.extend(c); violations.extend(v); query_words.extend(sp.validation_words)
        if seed == 0 or (seed+1)%10 == 0 or seed == 50:
            print(f'Verified static splits: {seed+1}/51', flush=True)
    proposed = _pack(rows, classes, violations, query_words, neighbors, dict(
        geometry=str(geo), reconstruction='Original static prepare_classification_split; 51 saved inventories matched',
        catalogue_sha256=hashlib.sha256((geo/'neighbors.json').read_bytes()).hexdigest(),
        module_sha256=hashlib.sha256(Path(module.__file__).read_bytes()).hexdigest(),
        embedding_subset_sha256=hashlib.sha256(embeddings.to_numpy(dtype='<f8').tobytes()).hexdigest(),
        embedding_word_order=list(embeddings.index), classifier_training_performed=False,
        minimum_class_frequency=3, pairwise_different_class=True))
    if _digest(ANTECEDENT_AUDIT) != ANTECEDENT_AUDIT_SHA256:
        raise RuntimeError('Embedded antecedent diagnostic was modified.')
    return _render_comparison(ANTECEDENT_AUDIT, proposed)

def _load_static(result, module=None, embedding_file=None, vectors=None):
    ctx = result.context
    if ctx.get("K") != 40 or len(ctx["labels"]) != 8:
        raise ValueError("This cell is for the audited eight-class GloVe50 K40 result.")
    project = Path(ctx["config"].project_root)
    if module is None or not hasattr(module, "prepare_classification_split"):
        path = project / "exp2_pipeline_integrated.py"
        spec = importlib.util.spec_from_file_location("_static_pair_reader", path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)

    folder = ctx.get("folder")
    geo = Path(folder) if folder is not None else Path(ctx["geometry_root"])/"K40"/"geometry"
    receipt_path = geo / "geometry_identity.json"
    if not receipt_path.exists():
        receipt_path = geo / "completed.json"
    receipt = json.loads(receipt_path.read_text(encoding="utf-8"))
    raw_neighbors = (geo / "neighbors.json").read_bytes()
    if hashlib.sha256(raw_neighbors).hexdigest() != receipt["outputs"]["neighbors.json"]:
        raise RuntimeError("Catalogue checksum mismatch.")
    neighbors = json.loads(raw_neighbors)
    labels = list(neighbors)
    if labels != list(ctx["labels"]):
        raise ValueError("Catalogue class order differs from the static result.")
    owner = {w: i for i, values in enumerate(neighbors.values()) for w in values}
    words = sorted(owner)
    if len(words) != sum(map(len, neighbors.values())):
        raise ValueError("Overlapping catalogue classes.")

    # Read only the required words from TXT, keeping RAM use small.
    source = "Provided in-memory DataFrame"
    if vectors is None:
        explicit = embedding_file or ctx.get("paths", {}).get("embedding_path")
        candidates = [Path(explicit)] if explicit is not None else []
        if explicit is None:
            for base in dict.fromkeys([project, project.parent, project.parent/"Data"]):
                for pattern in ("glove.6B.50d.txt", "*/glove.6B.50d.txt", "*/*/glove.6B.50d.txt"):
                    candidates.extend(sorted(base.glob(pattern)))
        candidates = list(dict.fromkeys(p.resolve() for p in candidates if p.is_file()))
        if not candidates:
            raise FileNotFoundError(
                "GloVe50 vectors were not found. Set GLOVE_FILE to the original "
                "glove.6B.50d.txt or its embedding DataFrame .pkl, then rerun this cell."
            )
        path = candidates[0]
        source = str(path)
        print("Reading vectors:", path)
        if path.suffix.lower() in (".pkl", ".pickle"):
            vectors = pd.read_pickle(path)
        elif path.suffix.lower() == ".txt":
            wanted, rows = set(words), {}
            with path.open(encoding="utf-8") as handle:
                for line in handle:
                    token, sep, values = line.rstrip().partition(" ")
                    if token in wanted:
                        if token in rows:
                            raise ValueError("Duplicate embedding word: " + token)
                        rows[token] = np.fromstring(values, sep=" ", dtype=float)
            vectors = pd.DataFrame.from_dict(rows, orient="index")
        else:
            raise ValueError("Use an embedding DataFrame .pkl or the original GloVe50 .txt.")
    if not isinstance(vectors, pd.DataFrame) or vectors.index.has_duplicates:
        raise ValueError("Expected a uniquely indexed embedding DataFrame.")
    missing = sorted(set(words) - set(vectors.index))
    if missing:
        raise ValueError("Catalogue words missing from the embedding file: " + str(missing[:15]))
    embeddings = vectors.loc[words].astype(float).copy()
    if embeddings.shape[1] != 50 or not np.isfinite(embeddings.values).all():
        raise ValueError("Expected finite, 50-dimensional GloVe embeddings.")

    return ctx, module, neighbors, embeddings, geo

